class LifecycleOrderTest {

    int counter;

    @BeforeEach
    void beforeEach() {
        counter = 10;
    }

    @Test
    void firstTest() {
        assertEquals(10, counter);
        counter = 999; // zmiana widoczna TYLKO w tej instancji
    }

    @Test
    void secondTest() {
        assertEquals(10, counter); // znowu 10, NIE 999 z firstTest
    }
}

@TestInstance(TestInstance.Lifecycle.PER_CLASS)
class PerClassLifecycleTest {

    int sharedCounter;

    @BeforeAll
    void beforeAllNotStatic() { // moze byc NIE-statyczne dzieki PER_CLASS
        sharedCounter = 100;
    }

    @Test
    void firstTest() {
        assertEquals(100, sharedCounter);
        sharedCounter = 200; // ta zmiana PRZETRWA do kolejnego testu
    }

    @Test
    void secondTest() {
        assertEquals(200, sharedCounter); // widzi zmiane z firstTest
    }
}

@TestInstance(TestInstance.Lifecycle.PER_CLASS)
class FragileTest {
    List<String> items = new ArrayList<>();

    @Test
    void firstTest() {
        items.add("a");
        assertEquals(1, items.size());
    }

    @Test
    void secondTest() {
        assertEquals(1, items.size()); // przechodzi TYLKO jesli firstTest wykonal sie wczesniej
    }
}

@TestInstance(TestInstance.Lifecycle.PER_CLASS)
class IndependentTest {
    List<String> items;

    @BeforeEach
    void resetState() {
        items = new ArrayList<>(); // swiezy stan przed KAZDYM testem
    }

    @Test
    void firstTest() {
        items.add("a");
        assertEquals(1, items.size());
    }

    @Test
    void secondTest() {
        assertEquals(0, items.size()); // niezalezne od firstTest
    }
}
